import React from 'react';
import { Link } from 'react-router-dom';

export default function Footer() {
  return (
    <footer style={{
      background: '#111',
      borderTop: '1px solid #1a1a1a',
      padding: '40px 24px',
      marginTop: 80,
    }}>
      <div style={{ maxWidth: 1200, margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 20 }}>
        <div>
          <div style={{ fontSize: 18, fontWeight: 900, marginBottom: 6 }}>
            All <span style={{ color: '#f97316' }}>Things</span>
          </div>
          <div style={{ color: '#555', fontSize: 13 }}>Social Media Marketing · Addis Ababa, Ethiopia</div>
        </div>
        <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
          {[['/', 'Home'], ['/clients', 'Clients'], ['/news', 'News'], ['/about', 'About'], ['/contact', 'Contact']].map(([to, label]) => (
            <Link key={to} to={to} style={{ color: '#555', fontSize: 13, transition: 'color 0.2s' }}
              onMouseEnter={e => e.target.style.color = '#f97316'}
              onMouseLeave={e => e.target.style.color = '#555'}>
              {label}
            </Link>
          ))}
        </div>
        <div style={{ color: '#333', fontSize: 12 }}>© 2026 All Things Marketing Agency</div>
      </div>
    </footer>
  );
}
